  'panel_login_page_Url' => 'URL da página de login do painel',
  'By enabling manual login, customers will get the option to create an account and log in using the necessary credentials & password in the app & website' => 'Ao ativar o login manual, os clientes terão a opção de criar uma conta e fazer login usando as credenciais e senha necessárias no aplicativo e site',
  'With OTP Login, customers can log in using their phone number. while new customers can create accounts instantly.' => 'Com o Login OTP, os clientes podem fazer login usando o número de telefone. ',
  'With Social Login, customers can log in using social media credentials. while new customers can create accounts instantly.' => 'Com o login social, os clientes podem fazer login usando credenciais de mídia social. ',
  'Enabling Google Login, customers can log in to the site using their existing Gmail credentials.' => 'Ativando o login do Google, os clientes podem fazer login no site usando suas credenciais existentes no Gmail.',
  'Enabling Facebook Login, customers can log in to the site using their existing Facebook credentials' => 'Ativando o login do Facebook, os clientes podem fazer login no site usando suas credenciais do Facebook existentes',
  'Enabling Apple Login, customers can log in to the site using their existing Apple login credentials, Only for Apple devices' => 'Ativando o Login da Apple, os clientes podem fazer login no site usando suas credenciais de login da Apple existentes, apenas para dispositivos Apple',
  'Verification' => 'Verificação',
  'The option you select from below will need to verify by customer from customer app/website.' => 'A opção que você selecionar abaixo precisará verificar pelo cliente do aplicativo/site do cliente.',
  'If Email verification is on, Customers must verify their email address with an OTP to complete the signup process.' => 'Se a verificação de email estiver ligada, os clientes devem verificar seu endereço de e -mail com um OTP para concluir o processo de inscrição.',
  'If Phone Number verification is on, Customers must verify their Phone Number with an OTP to complete the signup process.' => 'Se a verificação do número de telefone estiver ligada, os clientes devem verificar seu número de telefone com um OTP para concluir o processo de inscrição.',
  'Important Alert !' => 'Alerta importante!',
  'At least one login method must remain active for the customer; otherwise, they will be unable to log in to the system' => 'Pelo menos um método de login deve permanecer ativo para o cliente, caso contrário, eles não poderão fazer login no sistema',
  'Set Up SMS Configuration First' => 'Configure a configuração do SMS primeiro',
  'It looks like your SMS configuration is not set up yet. To enable the OTP system, please set up the SMS configuration first.' => 'Parece que sua configuração SMS ainda não foi configurada. ',
  'Go to SMS Configuration' => 'Vá para a configuração do SMS',
  'If you are activating only social login as the login method, you must enable at least one option between Google and Facebook for Android users.' => 'Se você estiver ativando apenas o login social como o método de login, deve permitir pelo menos uma opção entre o Google e o Facebook para usuários do Android.',
  'If you are activating social login as the login method, you must enable at least one option between Google, Facebook & Apple.' => 'Se você estiver ativando o login social como o método de login, deve ativar pelo menos uma opção entre o Google, Facebook e Apple.',
  'Set Up Google Configuration First' => 'Configure a configuração do Google primeiro',
  'It looks like your Google Login configuration is not set up yet. To enable the Google Login option, please set up the Google configuration first.' => 'Parece que sua configuração de login do Google ainda não foi configurada. ',
  'Go to Google Configuration' => 'Vá para a configuração do Google',
  'Set Up Facebook Configuration First' => 'Configure a configuração do Facebook primeiro',
  'It looks like your Facebook Login configuration is not set up yet. To enable the Facebook Login option, please set up the Facebook configuration first.' => 'Parece que sua configuração de login no Facebook ainda não está configurada. ',
  'Go to Facebook Configuration' => 'Vá para a configuração do Facebook',
  'Set Up Apple Configuration First' => 'Configure a configuração da Apple primeiro',
  'It looks like your Apple Login configuration is not set up yet. To enable the Apple Login option, please set up the Apple configuration first.' => 'Parece que sua configuração de login da Apple ainda não foi configurada. ',
  'Go to Apple Configuration' => 'Vá para a configuração da Apple',
  'It looks like your SMS configuration is not set up yet. To enable the phone verification, please set up the SMS configuration first.' => 'Parece que sua configuração SMS ainda não foi configurada. ',
